// sw.js — golf-swing-lab service worker (generated by scripts/build.mjs from app/sw.template.js; do not edit dist/sw.js).
//
// Caches (CAFCR R4, docs/app-architecture.md §7):
//   gsl-shell-<VERSION>  the app shell (html/css/js/icons/manifest), replaced as a whole on every new version
//   gsl-assets           large vendored files (wasm, .task models, vendor js), kept across versions; each entry
//                        carries its sha256 in the x-gsl-sha256 header and is re-fetched only when it changes
// All URLs are relative to the registration scope, so the same build works under / and /golf-swing-lab/.
// A new version installs in the background and waits; the page shows 「有新版本，點此更新」 and sends
// { type: 'SKIP_WAITING' } only when no practice session is running. Navigation requests get the cached
// index.html, so the app opens offline.

const MANIFEST = /*__GSL_MANIFEST__*/ { version: '0.0.0+template', dev: true, shell: ['index.html'], assets: [] } /*__GSL_MANIFEST_END__*/;

const VERSION = MANIFEST.version;
const SHELL_CACHE = `gsl-shell-${VERSION}`;
const ASSET_CACHE = 'gsl-assets';
const SHA_HEADER = 'x-gsl-sha256';

const scopeUrl = (p) => new URL(p, self.registration.scope).href;
const SHELL_URLS = MANIFEST.shell.map(scopeUrl);
const ASSET_BY_URL = new Map(MANIFEST.assets.map((a) => [scopeUrl(a.url), a]));
const INDEX_URL = scopeUrl('index.html');

async function putAsset(cache, url, asset, response) {
  const headers = new Headers(response.headers);
  headers.set(SHA_HEADER, asset.sha256);
  const body = await response.blob();
  await cache.put(url, new Response(body, { status: 200, statusText: 'OK', headers }));
}

async function cacheAsset(cache, url, asset) {
  const hit = await cache.match(url);
  if (hit && hit.headers.get(SHA_HEADER) === asset.sha256) return;
  const res = await fetch(new Request(url, { cache: 'reload' }));
  if (!res.ok) throw new Error(`precache ${url}: HTTP ${res.status}`);
  await putAsset(cache, url, asset, res);
}

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const shell = await caches.open(SHELL_CACHE);
    await shell.addAll(SHELL_URLS.map((u) => new Request(u, { cache: 'reload' })));
    const assets = await caches.open(ASSET_CACHE);
    for (const [url, a] of ASSET_BY_URL) if (a.precache) await cacheAsset(assets, url, a);
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const name of await caches.keys()) {
      if (name.startsWith('gsl-shell-') && name !== SHELL_CACHE) await caches.delete(name);
    }
    const assets = await caches.open(ASSET_CACHE);
    for (const req of await assets.keys()) {
      const a = ASSET_BY_URL.get(req.url);
      const hit = a ? await assets.match(req) : null;
      if (!a || !hit || hit.headers.get(SHA_HEADER) !== a.sha256) await assets.delete(req);
    }
    await self.clients.claim();
  })());
});

async function precacheComplete() {
  const shell = await caches.open(SHELL_CACHE);
  const assets = await caches.open(ASSET_CACHE);
  let total = 0;
  let have = 0;
  for (const u of SHELL_URLS) { total++; if (await shell.match(u)) have++; }
  for (const [u, a] of ASSET_BY_URL) {
    if (!a.precache) continue;
    total++;
    const hit = await assets.match(u);
    if (hit && hit.headers.get(SHA_HEADER) === a.sha256) have++;
  }
  return total ? have / total : 1;
}

self.addEventListener('message', (event) => {
  const type = event.data && event.data.type;
  if (type === 'SKIP_WAITING') self.skipWaiting();
  else if (type === 'GET_VERSION') {
    event.waitUntil(precacheComplete().then((frac) => {
      event.source && event.source.postMessage({ type: 'VERSION', version: VERSION, precache_complete: frac });
    }));
  }
});

async function fromShell(request, url) {
  const cache = await caches.open(SHELL_CACHE);
  if (MANIFEST.dev) {
    try {
      const res = await fetch(request);
      if (res.ok) await cache.put(url, res.clone());
      return res;
    } catch (_) { /* offline: fall through to the cache */ }
  }
  const hit = await cache.match(url);
  return hit || fetch(request);
}

// `keep(promise)` extends the fetch event's lifetime so the cache write finishes even after respondWith settles.
async function fromAssets(request, url, asset, keep) {
  const cache = await caches.open(ASSET_CACHE);
  const hit = await cache.match(url);
  if (hit && hit.headers.get(SHA_HEADER) === asset.sha256) return hit;
  const res = await fetch(request);
  if (res.ok && res.status === 200) {
    const copy = res.clone();
    keep(putAsset(cache, url, asset, copy).catch(() => {}));
  }
  return res;
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin || !req.url.startsWith(self.registration.scope)) return;
  const clean = url.origin + url.pathname;
  if (req.mode === 'navigate') {
    event.respondWith((async () => {
      const cache = await caches.open(SHELL_CACHE);
      if (MANIFEST.dev) {
        try { return await fetch(req); } catch (_) { /* offline */ }
      }
      const hit = await cache.match(INDEX_URL);
      return hit || fetch(req);
    })());
    return;
  }
  const asset = ASSET_BY_URL.get(clean);
  if (asset) {
    // waitUntil must be called during dispatch: hand it a promise settled once the background cache write is done.
    let done;
    event.waitUntil(new Promise((res) => { done = res; }));
    let pending = null;
    const work = fromAssets(req, clean, asset, (p) => { pending = p; });
    work.then(() => (pending || Promise.resolve()).then(done, done), done);
    event.respondWith(work);
    return;
  }
  if (SHELL_URLS.includes(clean)) { event.respondWith(fromShell(req, clean)); }
});
